"""B15: original CUET (UG) English items: Verbal Ability across all six VA topics + three new 200-300 word RC passages.
Keys are checked here: match-the-following keys are computed (never typed); rearrangements are checked against the
intended sentence; error-spotting keys are asserted against the part that contains the faulty token."""
import re, itertools
from batch_b2 import balanced, match_item

def words(html): return len(re.sub(r"<[^>]+>", " ", html).split())

def perms_except(key, picks):
    """Three distractor mappings: fixed picks from the list of permutations that differ from the key."""
    allp = [list(p) for p in itertools.permutations(range(4)) if list(p) != key]
    return [allp[i] for i in picks]

KEY = [3, 0, 2, 1]

def rearr(M, diff, parts, start, good, opts, sol, bad_valid=()):
    """parts: dict P/Q/R/S -> text; good: the intended order. Asserts the intended order rebuilds the sentence shown in the solution."""
    assert good in opts and len(set(opts)) == 4 and all(sorted(o) == list("PQRS") for o in opts)
    for b in bad_valid: assert b not in opts, b        # alternative orders that are also grammatical must not be offered
    sent = " ".join(parts[c] for c in good)
    assert sent.lower().strip(" .") in re.sub(r"\s*\([PQRS]\)", "", sol).lower(), (sent, sol)
    head = "Rearrange the parts to form a meaningful sentence:" if not start else f"The sentence begins: '{start}…'. Rearrange the parts to complete it:"
    text = head + "<br>" + " &nbsp; ".join(f"{c}: {parts[c]}" for c in "PQRS")
    M("Verbal Ability", "Rearranging the parts", diff, text, opts, good, sol)

def err(M, diff, parts, wrong, fix, sol):
    """parts: four strings; wrong: the faulty substring, which must occur in exactly one part; that part is the key."""
    hit = [i for i, p in enumerate(parts) if wrong in p]; assert len(hit) == 1, (wrong, parts)
    key = "ABCD"[hit[0]]
    fixed_s = " ".join(parts).replace(wrong, fix)
    assert fixed_s != " ".join(parts)
    text = "Identify the part of the sentence that contains an error: " + " / ".join(f"({'ABCD'[i]}) {p}" for i, p in enumerate(parts))
    M("Verbal Ability", "Error spotting", diff, text, ["A", "B", "C", "D"], key, sol + f" Corrected: '{fixed_s}'", fixed=True)
    return key

PASSAGES = {
"cu-treerings": ("Factual passage: Reading the rings of trees", """<p>Cut across the trunk of an old oak and you will see a series of rings, one for each year of the tree's life. In spring a tree grows quickly and makes wide, pale cells; by late summer growth slows and the cells become small and dark. The sharp boundary between one summer's dark wood and the next spring's pale wood marks the edge of a year.</p>
<p>Counting rings gives a tree's age, but their real value lies in their widths. In a wet, mild year a tree lays down a broad ring; in a year of drought, a narrow one. Because every tree in a region feels the same weather, trees of the same species there share the same pattern of wide and narrow rings, much as people in one town share memories of the same hard winters.</p>
<p>This shared pattern lets scientists reach far beyond the life of any single tree. The inner rings of a living tree can be matched with the outer rings of a beam from an old building, whose inner rings can then be matched with timber older still. Linked in this way, overlapping pieces of wood have produced continuous records thousands of years long.</p>
<p>Such records have practical uses. A wooden panel on which a painting was made can be dated, and so can a ship found on the seabed. Ring patterns also preserve a history of past droughts long before anyone measured rainfall, a history that helps planners judge how severe a dry spell might one day become.</p>"""),
"cu-placebo": ("Discursive passage: The honest placebo", """<p>A placebo is a treatment with no active ingredient, such as a sugar pill. For decades doctors assumed that it could work only if the patient was deceived. If you knew the pill was sugar, the reasoning went, your expectation of relief would vanish, and with it any benefit.</p>
<p>A series of small trials has challenged this assumption. Patients with certain long-lasting conditions, such as some kinds of back pain, were handed bottles plainly labelled as placebo and told exactly what was inside. Many nevertheless reported less discomfort than patients who received no pills at all. The researchers suggest that the ritual of treatment, the act of taking something regularly with care and attention, may itself prompt the body and mind to respond.</p>
<p>The finding is attractive because it seems to remove an ethical problem. Giving fake medicine without telling the patient is a kind of lying; an honest placebo involves no lie at all. Yet caution is needed. The trials have mostly been short and small, and the conditions studied are ones in which patients themselves report how they feel. A sugar pill may make a headache feel less severe; there is no good evidence that it can shrink a tumour or cure an infection.</p>
<p>The lesson, then, is narrower than the headlines suggest. Honest placebos are not a substitute for medicine. What they may show is that the way care is given, including the time and attention a patient receives, is not merely decoration around a treatment but can be part of it.</p>"""),
"cu-lighthouse": ("Literary passage: The last keeper", """<p>For thirty-one years Joseph Fernandes had climbed the hundred and twelve steps of the lighthouse every evening at dusk. He knew each step by its sound: the seventh rang slightly, the fortieth had a crack his boot always found, and the last ten groaned like an old man rising from a chair. At the top he would wipe the great lens, light the lamp and write the time in a ledger that nobody but the inspector ever read.</p>
<p>The letter from the department was polite. The light would be made automatic in March; a small machine would switch it on and off by itself, and a technician would visit twice a year. His service, it said, had been "much appreciated". Joseph read it twice, folded it into a careful square and put it under the clock.</p>
<p>On his last evening his granddaughter came with him. She counted the steps aloud and complained halfway up. At the top she pressed her face to the glass and watched the beam sweep out across the dark water, catching for an instant the white edge of a fishing boat.</p>
<p>"Does the machine know about the boats?" she asked.</p>
<p>Joseph considered this. "The machine knows when it is dark," he said at last. "That is most of the job."</p>
<p>He wrote the time in the ledger, and then, after a moment, he wrote something else beneath it, which he did not let her read.</p>"""),
}

def english(B):
    M = balanced(B, "english", 1515)
    VA, RC = "Verbal Ability", "Reading Comprehension"
    for sid, (title, html) in PASSAGES.items():
        n = words(html); assert 200 <= n <= 300, (sid, n)
        B.add_set(sid, "passage", title, f"<b>{title}</b>{html}")
    P = {k: re.sub(r"<[^>]+>", " ", v[1]) for k, v in PASSAGES.items()}

    # ---------------- Synonyms & Antonyms (+5)
    S = "Synonyms & Antonyms"
    M(VA,S,"Medium","Choose the word closest in meaning to CORROBORATE.",["Confirm","Collaborate","Contradict","Corrode"],"Confirm","To corroborate is to confirm or support a statement with further evidence (a witness corroborates an alibi). 'Collaborate' (work together) and 'corrode' (wear away) only look similar; 'contradict' is nearly the opposite.")
    M(VA,S,"Medium","Choose the word closest in meaning to SPURIOUS.",["False","Spirited","Genuine","Curious"],"False","Spurious means false or not what it claims to be (a spurious claim, a spurious coin). 'Genuine' is its opposite; 'spirited' and 'curious' are sound-alike traps.")
    M(VA,S,"Hard","Choose the word closest in meaning to AUSTERE.",["Severely plain","Highly decorated","Deeply anxious","Freely generous"],"Severely plain","Austere means severe or strict in manner, and plain and without luxury in style (an austere room, an austere life). 'Highly decorated' is the opposite sense; the other two are unrelated.")
    M(VA,S,"Easy","Choose the word most nearly OPPOSITE in meaning to ZENITH.",["Nadir","Summit","Climax","Horizon"],"Nadir","The zenith is the highest point; the nadir is the lowest point. 'Summit' and 'climax' are near-synonyms of zenith, and the horizon is not an extreme at all.")
    M(VA,S,"Hard","Choose the word most nearly OPPOSITE in meaning to LOQUACIOUS.",["Taciturn","Garrulous","Eloquent","Voluble"],"Taciturn","Loquacious means very talkative. 'Garrulous' and 'voluble' are synonyms of it, and 'eloquent' (fluent and persuasive) is also about speaking well. Taciturn, meaning saying very little, is the opposite.")

    # ---------------- Choosing the correct word (+7)
    C = "Choosing the correct word"
    M(VA,C,"Easy","Fill in the blank: My teacher's ______ helped me choose the right subjects.",["advice","advise","advices","advised"],"advice","A noun is needed after the possessive 'teacher's'. 'Advice' is the noun and is uncountable, so 'advices' is wrong; 'advise' is the verb and 'advised' is its past form.")
    M(VA,C,"Medium","Fill in the blank: The new timetable will ______ every student who joined after April.",["affect","effect","infect","afflict"],"affect","'Affect' is the verb meaning 'to have an influence on'. 'Effect' is normally a noun (as a verb it means 'to bring about', which does not fit), 'infect' refers to disease, and 'afflict' means to cause suffering.")
    M(VA,C,"Hard","Fill in the blank: Hardly had we reached the platform ______ the train began to move.",["when","than","then","that"],"when","'Hardly' and 'scarcely' pair with 'when' (or 'before'): 'Hardly had we reached … when …'. 'Than' belongs with 'no sooner'; 'then' and 'that' do not complete the construction.")
    M(VA,C,"Medium","Fill in the blank: The firm has lost money for three years running; ______, it has decided to close two branches.",["consequently","nevertheless","meanwhile","otherwise"],"consequently","Closing branches is a result of the losses, so a connector of result is needed: 'consequently'. 'Nevertheless' signals contrast, 'meanwhile' signals simultaneous time, and 'otherwise' signals an alternative.")
    M(VA,C,"Easy","Fill in the blank: One of my cousins ______ in Chennai.",["lives","live","are living","have lived"],"lives","The subject is 'one' (not 'cousins'), which is singular, so the verb must be singular: 'lives'. The other three are plural forms.")
    M(VA,C,"Medium","Fill in the blank: After the quarrel, the two brothers stopped speaking to ______.",["each other","one other","themselves","ourselves"],"each other","A reciprocal pronoun is needed (each brother stopped speaking to the other): 'each other'. 'Themselves' would mean each spoke to himself, 'ourselves' does not match the subject, and 'one other' is not a reciprocal pronoun.")
    M(VA,C,"Medium","Fill in the blank: If it ______ tomorrow, the match will be postponed.",["rains","will rain","rained","would rain"],"rains","In a first conditional the if-clause takes the simple present and the main clause takes 'will': 'If it rains tomorrow, the match will be postponed.' 'Will rain' is not used in the if-clause, and 'rained/would rain' belong to the second conditional.")

    # ---------------- Error spotting (+8)
    e = []
    e.append(err(M,"Easy",["The furniture", "in these rooms", "are very old", "and needs polishing."],"are very old","is very old","'Furniture' is an uncountable noun and takes a singular verb, as part D already shows ('needs'). So 'are' in part C must be 'is'."))
    e.append(err(M,"Hard",["He is one of those people", "who always tries", "to help", "others in need."],"who always tries","who always try","The relative pronoun 'who' refers to 'those people' (plural), not to 'one', so its verb must be plural: 'who always try'. The error is in part B."))
    e.append(err(M,"Medium",["No sooner did the bell ring", "when the children", "rushed out", "of the classroom."],"when the children","than the children","'No sooner' is always followed by 'than', not 'when'. The error is in part B."))
    e.append(err(M,"Medium",["I prefer reading novels", "than watching", "films on", "my phone."],"than watching","to watching","'Prefer' takes 'to' for the second item: 'prefer reading novels to watching films'. The error is in part B."))
    e.append(err(M,"Hard",["Ten kilometres", "are a long distance", "to walk", "in this heat."],"are a long distance","is a long distance","A plural amount treated as a single quantity (a distance, a sum of money, a period of time) takes a singular verb: 'Ten kilometres is a long distance'. The error is in part B."))
    e.append(err(M,"Medium",["Scarcely had I", "opened the door", "than the cat", "ran inside."],"than the cat","when the cat","'Scarcely' (like 'hardly') pairs with 'when' or 'before', not 'than'. The error is in part C."))
    e.append(err(M,"Easy",["The police has", "arrested the man", "who stole", "the bicycle."],"The police has","The police have","'Police' is a plural noun in English and takes a plural verb: 'The police have arrested …'. The error is in part A."))
    e.append(err(M,"Medium",["Unless you do not", "work hard,", "you will not", "pass the examination."],"Unless you do not","Unless you","'Unless' already means 'if not', so adding 'do not' creates a double negative. It should be 'Unless you work hard, you will not pass'. The error is in part A."))
    assert len(set(e)) >= 3                      # keys spread over several positions

    # ---------------- Rearranging the parts (+8)
    rearr(M,"Easy",{"P":"the importance of saving water","Q":"the village council","R":"through street plays","S":"explained to the residents"},None,"QSPR",["QSPR","SQPR","PQSR","QPRS"],"'The village council (Q) explained to the residents (S) the importance of saving water (P) through street plays (R).' Subject, verb with its indirect object, the thing explained, then the means.")
    rearr(M,"Easy",{"P":"was postponed","Q":"because of the heavy rain","R":"the cricket match","S":"scheduled for Sunday"},None,"RSPQ",["RSPQ","RPSQ","SRPQ","PRSQ"],"'The cricket match (R) scheduled for Sunday (S) was postponed (P) because of the heavy rain (Q).' The phrase 'scheduled for Sunday' must follow the noun it describes.",bad_valid=["QRSP"])
    rearr(M,"Hard",{"P":"did he realise","Q":"after he had left the house","R":"his phone","S":"that he had forgotten"},"Only","QPSR",["QPSR","QSPR","PQSR","QRPS"],"'Only after he had left the house (Q) did he realise (P) that he had forgotten (S) his phone (R).' A sentence opening with 'Only after …' requires inversion in the main clause ('did he realise'), which must come directly after the time clause.")
    rearr(M,"Medium",{"P":"a balanced diet","Q":"doctors recommend","R":"and regular exercise","S":"for a healthy life"},None,"QPRS",["QPRS","PQRS","RPQS","SQRP"],"'Doctors recommend (Q) a balanced diet (P) and regular exercise (R) for a healthy life (S).' 'And regular exercise' must follow the first item it is joined to.",bad_valid=["PRQS","QSPR"])
    rearr(M,"Medium",{"P":"who had been missing for two days","Q":"the police found","R":"the little boy","S":"in a nearby forest"},None,"QRPS",["QRPS","QPRS","RSQP","PQSR"],"'The police found (Q) the little boy (R) who had been missing for two days (P) in a nearby forest (S).' The relative clause must come right after 'the little boy', the person it describes.",bad_valid=["QRSP","RPQS"])
    rearr(M,"Hard",{"P":"but also writes her own songs","Q":"not only sings","R":"the young artist","S":"beautifully"},None,"RQSP",["RQSP","RSQP","QRSP","RQPS"],"'The young artist (R) not only sings (Q) beautifully (S) but also writes her own songs (P).' 'Not only' must come before 'but also', and the adverb 'beautifully' belongs with 'sings'.")
    rearr(M,"Medium",{"P":"than any other student","Q":"worked harder","R":"in the class","S":"Priya"},None,"SQPR",["SQPR","SPQR","QSRP","PRSQ"],"'Priya (S) worked harder (Q) than any other student (P) in the class (R).' The comparison 'than any other student' is completed by 'in the class'.",bad_valid=["SQRP"])
    rearr(M,"Easy",{"P":"the bridge","Q":"built over a century ago","R":"still carries","S":"heavy traffic every day"},None,"PQRS",["PQRS","PRQS","SRPQ","RPQS"],"'The bridge (P) built over a century ago (Q) still carries (R) heavy traffic every day (S).' The participle phrase describes the bridge and is followed by the verb and its object.",bad_valid=["QPRS"])

    # ---------------- Match the following (+7)
    match_item(M,"Medium","Match each word in List I with its meaning in List II.",[("Verbose","using more words than needed"),("Ominous","suggesting that something bad will happen"),("Resilient","able to recover quickly from difficulty"),("Tenacious","holding firmly to a purpose")],perms_except(KEY,[2,9,17]),"These are the standard dictionary senses of the four words.")
    match_item(M,"Easy","Match each idiom in List I with its meaning in List II.",[("A piece of cake","something very easy"),("Once in a blue moon","very rarely"),("To spill the beans","to reveal a secret"),("To hit the sack","to go to bed")],perms_except(KEY,[4,12,20]),"These are the accepted meanings of the four idioms.")
    match_item(M,"Easy","Match each collective phrase in List I with the noun it is used for in List II.",[("A pride of","lions"),("A swarm of","bees"),("A school of","fish"),("A herd of","cattle")],perms_except(KEY,[1,11,19]),"A pride of lions, a swarm of bees, a school of fish and a herd of cattle are the standard collective expressions.")
    match_item(M,"Medium","Match each word in List I with its antonym in List II.",[("Optimist","pessimist"),("Benign","malignant"),("Lenient","strict"),("Affluent","impoverished")],perms_except(KEY,[6,14,21]),"Each pair is a standard pair of opposites: hopeful/gloomy, harmless/harmful, mild/severe in discipline, and rich/poor.")
    match_item(M,"Hard","Match each figure of speech in List I with its example in List II.",[("Oxymoron","a deafening silence"),("Onomatopoeia","the buzz of the bees"),("Hyperbole","I have told you a million times."),("Irony","The fire station burned down.")],perms_except(KEY,[3,10,16]),"An oxymoron joins contradictory words; onomatopoeia imitates a sound; hyperbole is deliberate exaggeration; irony (here, situational) is an outcome opposite to what one would expect.")
    match_item(M,"Medium","Match each phrasal verb in List I with its meaning in List II.",[("Put off","postpone"),("Give up","stop trying"),("Look after","take care of"),("Turn down","reject")],perms_except(KEY,[0,8,15]),"These are the common meanings of the four phrasal verbs.")
    match_item(M,"Hard","Match each specialist in List I with what he or she studies or collects in List II.",[("Ornithologist","birds"),("Entomologist","insects"),("Seismologist","earthquakes"),("Numismatist","coins")],perms_except(KEY,[5,13,22]),"Ornith- (bird), entomo- (insect), seismo- (shaking) and numism- (coin) give the four meanings. Entomologist is often confused with etymologist, who studies word origins.")

    # ---------------- One-word substitution (+8)
    O = "One-word substitution"
    q = "Choose the one word that can replace the phrase: "
    M(VA,O,"Medium",q+"a person who walks in his or her sleep.",["Somnambulist","Insomniac","Pedestrian","Hypochondriac"],"Somnambulist","Somnambulist (Latin somnus 'sleep' + ambulare 'to walk') is a sleepwalker. An insomniac cannot sleep, a pedestrian walks on the road, and a hypochondriac worries excessively about illness.")
    M(VA,O,"Medium",q+"a remedy for all diseases or problems.",["Panacea","Placebo","Antidote","Vaccine"],"Panacea","A panacea is a cure-all. A placebo is a dummy treatment, an antidote counters one particular poison, and a vaccine protects against one particular disease.")
    M(VA,O,"Easy",q+"an extreme fear of heights.",["Acrophobia","Claustrophobia","Hydrophobia","Agoraphobia"],"Acrophobia","Acro- means height or top. Claustrophobia is fear of enclosed spaces, hydrophobia of water, and agoraphobia of open or crowded public places.")
    M(VA,O,"Medium",q+"handwriting that cannot be read.",["Illegible","Ineligible","Indelible","Inaudible"],"Illegible","Illegible means not readable. Ineligible means not qualified, indelible means impossible to erase, and inaudible means impossible to hear.")
    M(VA,O,"Easy",q+"a person who eats far too much.",["Glutton","Gourmet","Carnivore","Cannibal"],"Glutton","A glutton eats excessively. A gourmet is a connoisseur of fine food, a carnivore eats meat, and a cannibal eats the flesh of its own kind.")
    M(VA,O,"Easy",q+"a list of items to be discussed at a meeting.",["Agenda","Minutes","Itinerary","Memorandum"],"Agenda","The agenda is the list drawn up before a meeting; the minutes record what was said afterwards. An itinerary is a travel plan and a memorandum is a written note or message.")
    M(VA,O,"Hard",q+"a person who endures pain or hardship without showing feelings or complaining.",["Stoic","Cynic","Sceptic","Hedonist"],"Stoic","A stoic bears hardship calmly. A cynic distrusts people's motives, a sceptic doubts claims, and a hedonist pursues pleasure, which is nearly the opposite.")
    M(VA,O,"Hard",q+"words written on a tombstone in memory of the person buried there.",["Epitaph","Epigram","Epilogue","Epithet"],"Epitaph","An epitaph is the inscription on a tomb. An epigram is a short witty saying, an epilogue is a closing section of a book or play, and an epithet is a descriptive name such as 'Alexander the Great'.")

    # ---------------- RC: tree rings
    t = "cu-treerings"; p = P[t]
    assert "wide, pale cells" in p and "small and dark" in p and "In a wet, mild year a tree lays down a broad ring" in p and "inner rings of a living tree can be matched with the outer rings" in p
    M(RC,"Reading Comprehension","Easy","According to the passage, the boundary that marks the end of one year's growth lies between:",["the small, dark late-summer wood and the next spring's wide, pale wood","two pale rings formed in the same spring","the bark and the outermost ring","a wide ring and a narrow ring"],"the small, dark late-summer wood and the next spring's wide, pale wood","Paragraph 1: 'The sharp boundary between one summer's dark wood and the next spring's pale wood marks the edge of a year.' Ring width (wide or narrow) is about weather, not the year boundary, and the bark is not discussed.",set_id=t)
    M(RC,"Reading Comprehension","Medium","A tree shows an unusually narrow ring for a particular year. By the passage's account, that year was most probably:",["dry","wet and mild","the year the tree was planted","a year in which the tree was cut"],"dry","Paragraph 2: 'In a wet, mild year a tree lays down a broad ring; in a year of drought, a narrow one.' So a narrow ring points to drought. Planting or cutting is not linked to ring width.",set_id=t)
    M(RC,"Reading Comprehension","Medium","The comparison with 'people in one town' who 'share memories of the same hard winters' is used to explain why:",["trees of one species in a region show the same pattern of wide and narrow rings","old trees remember past weather better than young ones","towns were often built from local timber","people can estimate a tree's age by looking at it"],"trees of one species in a region show the same pattern of wide and narrow rings","The simile follows 'every tree in a region feels the same weather', so trees there 'share the same pattern', just as townspeople share memories of the same winters. It is an analogy for a common record, not a claim about memory, building or estimating age.",set_id=t)
    M(RC,"Reading Comprehension","Hard","Records 'thousands of years long' are possible mainly because:",["the ring patterns of overlapping pieces of wood of different ages can be matched and linked","some living trees are thousands of years old","rainfall has been measured for thousands of years","paintings and ships record the dates on which they were made"],"the ring patterns of overlapping pieces of wood of different ages can be matched and linked","Paragraph 3 says the shared pattern lets scientists 'reach far beyond the life of any single tree' by matching a living tree with an old beam, and that beam with older timber. The passage does not rely on very old living trees; rainfall records are said not to go back that far ('long before anyone measured rainfall'); and paintings and ships are things dated by the method, not sources for it.",set_id=t)

    # ---------------- RC: honest placebo
    t = "cu-placebo"; p = P[t]
    assert "plainly labelled as placebo" in p and "ritual of treatment" in p and "kind of lying" in p and "shrink a tumour" in p and "not a substitute for medicine" in p
    M(RC,"Reading Comprehension","Easy","What assumption about placebos do the trials described in the passage challenge?",["That a placebo can work only if the patient is deceived","That a placebo contains no active ingredient","That back pain is a long-lasting condition","That sugar pills are cheap to produce"],"That a placebo can work only if the patient is deceived","Paragraph 1 states the old assumption: a placebo 'could work only if the patient was deceived'. Paragraph 2 says the trials 'challenged this assumption' by telling patients exactly what they were taking. The other options are not under challenge.",set_id=t)
    M(RC,"Reading Comprehension","Medium","According to the researchers, honest placebos may work because:",["the ritual of taking a treatment with care and attention may itself prompt a response","patients secretly believe the pills contain medicine","sugar has a mild pain-relieving effect","doctors give the pills only to patients who are already recovering"],"the ritual of taking a treatment with care and attention may itself prompt a response","Paragraph 2: 'the ritual of treatment, the act of taking something regularly with care and attention, may itself prompt the body and mind to respond.' The passage gives no support for secret belief, an effect of sugar, or selective prescribing.",set_id=t)
    M(RC,"Reading Comprehension","Hard","The author mentions that the conditions studied are 'ones in which patients themselves report how they feel' in order to:",["suggest that the benefits found may be limited to how symptoms are felt, not to measurable disease","prove that the patients in the trials were not telling the truth","argue that honest placebos should replace pain medicines","show that the trials were too large to be reliable"],"suggest that the benefits found may be limited to how symptoms are felt, not to measurable disease","The remark is part of the author's 'caution', and is followed by the contrast between a headache feeling less severe and shrinking a tumour. The point is a limit on what has been shown, not an accusation of lying. 'Should replace pain medicines' contradicts 'not a substitute', and the trials are called small, not large.",set_id=t)
    M(RC,"Reading Comprehension","Medium","Which statement best expresses the author's conclusion?",["The way care is given can be part of a treatment, though honest placebos cannot replace real medicine","Honest placebos are as effective as most medicines","Placebos are unethical and should not be used","The trials prove that the mind can cure any illness"],"The way care is given can be part of a treatment, though honest placebos cannot replace real medicine","The final paragraph says honest placebos 'are not a substitute for medicine' but may show that the way care is given 'can be part of' treatment. 'As effective as most medicines' and 'cure any illness' overstate the evidence, and the passage praises honest placebos for removing the ethical problem rather than calling them unethical.",set_id=t)

    # ---------------- RC: lighthouse
    t = "cu-lighthouse"; p = P[t]
    assert "thirty-one years" in p and "automatic in March" in p and "folded it into a careful square" in p and "That is most of the job" in p
    M(RC,"Reading Comprehension","Easy","Why was this Joseph's last evening at the lighthouse?",["The light was being made automatic, so a keeper was no longer needed","He had been dismissed after an inspector's visit","His granddaughter had asked him to stop working","The lighthouse was being closed to shipping"],"The light was being made automatic, so a keeper was no longer needed","The department's letter says the light 'would be made automatic in March' with a machine switching it on and off and a technician visiting twice a year. Nothing suggests dismissal, a request from the granddaughter, or closure of the light.",set_id=t)
    M(RC,"Reading Comprehension","Medium","The detail that Joseph knew 'each step by its sound' mainly suggests:",["how long and closely he had lived with the lighthouse","that the staircase was dangerous and needed repair","that he had poor eyesight","that he disliked climbing the steps"],"how long and closely he had lived with the lighthouse","After thirty-one years of nightly climbs he knows the seventh step rings and the fortieth is cracked; the detail conveys intimate familiarity. The passage gives no hint of danger, poor eyesight or dislike.",set_id=t)
    M(RC,"Reading Comprehension","Hard","Joseph's reply, 'The machine knows when it is dark. That is most of the job,' most likely reveals:",["a quiet acceptance mixed with the sense that something the machine cannot do is being lost","his belief that the machine will do the work better than he did","anger at the department for replacing him","that he wants to frighten his granddaughter about the boats"],"a quiet acceptance mixed with the sense that something the machine cannot do is being lost","He pauses ('considered this'), concedes that the machine covers 'most' of the job, and so implies a remainder (attention to the boats) it cannot cover. The tone is restrained, not angry, and he neither praises the machine as better nor tries to frighten the girl.",set_id=t)
    M(RC,"Reading Comprehension","Medium","How does Joseph respond to the department's letter?",["With restraint: he reads it twice, folds it carefully and puts it away","With open anger, tearing it up","By writing a letter of protest","By telling his granddaughter about it at once"],"With restraint: he reads it twice, folds it carefully and puts it away","'Joseph read it twice, folded it into a careful square and put it under the clock.' The careful, silent handling shows restraint. There is no tearing, protest letter or immediate telling.",set_id=t)
